PRAGMA foreign_keys=ON;
CREATE TABLE accounts(id TEXT PRIMARY KEY,email TEXT UNIQUE NOT NULL,name TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN ('admin','teacher','student','parent')),password_hash TEXT NOT NULL,salt TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE auth_sessions(token_hash TEXT PRIMARY KEY,account_id TEXT NOT NULL REFERENCES accounts(id),expires_at INTEGER NOT NULL);
CREATE TABLE login_limits(key TEXT PRIMARY KEY,attempts INTEGER NOT NULL,reset_at INTEGER NOT NULL);
CREATE TABLE learners(id TEXT PRIMARY KEY,account_id TEXT UNIQUE REFERENCES accounts(id),alias TEXT NOT NULL,grade INTEGER NOT NULL,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE classes(id TEXT PRIMARY KEY,name TEXT NOT NULL,grade INTEGER NOT NULL,locale TEXT NOT NULL,teacher_id TEXT NOT NULL REFERENCES accounts(id));
CREATE TABLE enrollments(class_id TEXT REFERENCES classes(id),learner_id TEXT REFERENCES learners(id),PRIMARY KEY(class_id,learner_id));
CREATE TABLE guardianships(parent_id TEXT REFERENCES accounts(id),learner_id TEXT REFERENCES learners(id),PRIMARY KEY(parent_id,learner_id));
CREATE TABLE invitations(token_hash TEXT PRIMARY KEY,learner_id TEXT REFERENCES learners(id),expires_at INTEGER NOT NULL,used_at TEXT);
CREATE TABLE questions(id TEXT PRIMARY KEY,logical_id TEXT NOT NULL,grade INTEGER NOT NULL,locale TEXT NOT NULL,module TEXT NOT NULL,title TEXT NOT NULL,prompt TEXT NOT NULL,script TEXT NOT NULL,teacher_notes TEXT NOT NULL DEFAULT '',response_type TEXT NOT NULL,options TEXT NOT NULL DEFAULT '[]',answer TEXT NOT NULL DEFAULT '',explanation TEXT NOT NULL DEFAULT '',status TEXT NOT NULL DEFAULT 'draft',text_policy TEXT NOT NULL DEFAULT 'full',version INTEGER NOT NULL DEFAULT 1,source TEXT NOT NULL,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE assignments(id TEXT PRIMARY KEY,class_id TEXT NOT NULL REFERENCES classes(id),teacher_id TEXT NOT NULL REFERENCES accounts(id),title TEXT NOT NULL,due_at TEXT NOT NULL,question_ids TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'published',created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE classrooms(id TEXT PRIMARY KEY,class_id TEXT REFERENCES classes(id),teacher_id TEXT REFERENCES accounts(id),title TEXT NOT NULL,code TEXT UNIQUE NOT NULL,question_ids TEXT NOT NULL,current_index INTEGER NOT NULL DEFAULT 0,round INTEGER NOT NULL DEFAULT 1,phase TEXT NOT NULL DEFAULT 'reading',text_visible INTEGER NOT NULL DEFAULT 1,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE attempts(id TEXT PRIMARY KEY,request_id TEXT NOT NULL UNIQUE,learner_id TEXT NOT NULL REFERENCES learners(id),question_id TEXT NOT NULL REFERENCES questions(id),question_snapshot TEXT NOT NULL,context TEXT NOT NULL CHECK(context IN ('private','assignment','classroom')),context_id TEXT,round INTEGER NOT NULL DEFAULT 1,answer TEXT NOT NULL,status TEXT NOT NULL,feedback TEXT,score INTEGER,audio_source TEXT NOT NULL DEFAULT 'none',hint_used INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX classroom_one_submission ON attempts(learner_id,context_id,round) WHERE context='classroom';
CREATE INDEX attempts_learner ON attempts(learner_id,context,created_at);
CREATE TABLE audio_assets(id TEXT PRIMARY KEY,question_id TEXT NOT NULL REFERENCES questions(id),owner_id TEXT REFERENCES accounts(id),kind TEXT NOT NULL,mime TEXT NOT NULL,r2_key TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'draft',created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE audit_log(id TEXT PRIMARY KEY,actor_id TEXT,action TEXT NOT NULL,resource_id TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
